questions:
[
  {
    "n": 1,
    "type": "ståndpunkt",
    "stem": "Vad är textförfattarens huvudsakliga ståndpunkt?",
    "options": {
      "A": "Att regleringen mest är ekonomiskt ineffektiv och bör ersättas av en helt fri hyresmarknad utan riktade stöd.",
      "B": "Att staten själv bör bygga betydligt fler hyresrätter i egen regi för att möta den växande stadsbefolkningen.",
      "C": "Att regleringen missgynnar de svaga den ska skydda och att stödet bör gå till hushållet, inte bostaden.",
      "D": "Att hushållens växande skuldsättning är det allvarligaste hotet mot svensk ekonomi och måste pressas ned."
    },
    "correct": "C",
    "passage_anchor": "Att försvara systemet i dess nuvarande form är inte att stå på de utsattas sida — det är att cementera deras utanförskap. […] Den som vill värna de svaga bör rikta stödet direkt till hushållet, inte till en bostad vars låga hyra råkar tillfalla den som för tillfället bor i den.",
    "explanation": "Texten säger att regleringen blivit ett hinder för de svaga den skulle skydda, och att stödet bör riktas till hushållet snarare än till bostaden — svaret väger ihop tesen och den föreslagna lösningen.",
    "distractor_types": {
      "A": "nära_men_inte_riktigt",
      "B": "ytlig_nyckelordsläsning",
      "D": "sant_men_fel_fråga"
    },
    "notes": ""
  },
  {
    "n": 2,
    "type": "ståndpunkt",
    "stem": "Hur bemöter författaren invändningen att en avreglering skulle drabba låginkomsttagare?",
    "options": {
      "A": "Att de utan förstahandskontrakt redan betalar marknadspris i andra hand och därför missgynnas, inte skyddas.",
      "B": "Att invändningen i grunden stämmer och att låginkomsttagare därför bör undantas från en kommande avreglering.",
      "C": "Att hushållens skuldsättning oroar Riksbanken och utgör ett växande hot mot den finansiella stabiliteten.",
      "D": "Att låginkomsttagare gynnas mer av ett riktat bostadsbidrag än av dagens generellt nedhållna hyror."
    },
    "correct": "A",
    "passage_anchor": "Men den gruppen är redan systematiskt marginaliserad av dagens ordning. Den som inte ärvt ett kontrakt eller stått i kö sedan tonåren betalar i praktiken marknadshyra ändå, fast i andra hand och utan besittningsskydd.",
    "explanation": "Författaren bemöter invändningen med att gruppen redan är marginaliserad och i praktiken betalar marknadshyra i andra hand.",
    "distractor_types": {
      "B": "ytlig_nyckelordsläsning",
      "C": "sant_men_fel_fråga",
      "D": "nära_men_inte_riktigt"
    },
    "notes": ""
  },
  {
    "n": 3,
    "type": "detalj_fakta",
    "stem": "Vad framgår av texten om den finländska avvecklingen av hyresregleringen?",
    "options": {
      "A": "Att hyrorna efter en inledande uppgång stabiliserades när byggandet tog fart och att rörligheten ökade.",
      "B": "Att hyrorna sjönk i stort sett direkt efter avvecklingen tack vare ett snabbt ökande bostadsbyggande.",
      "C": "Att avvecklingen genomfördes abrupt och utlöste en omfattande social oro runt om i landet.",
      "D": "Att Finland behöll reglerade hyror i det äldre beståndet men släppte nyproduktionen helt fri."
    },
    "correct": "A",
    "passage_anchor": "Erfarenheterna från Finland, som under nittiotalet avvecklade sin hyresreglering, visar att hyrorna efter en inledande uppgång stabiliserades när nyproduktionen tog fart — och att rörligheten på marknaden ökade så att fler hushåll kunde flytta dit arbete och studier fanns.",
    "explanation": "Enligt anchoret steg hyrorna först och stabiliserades sedan när byggandet ökade, samtidigt som rörligheten på marknaden ökade.",
    "distractor_types": {
      "B": "nära_men_inte_riktigt",
      "C": "ytlig_nyckelordsläsning",
      "D": "sant_men_fel_fråga"
    },
    "notes": ""
  },
  {
    "n": 4,
    "type": "huvudtanke",
    "stem": "Vilken alternativ rubrik sammanfattar textens huvudinnehåll bäst?",
    "options": {
      "A": "När skyddet stänger ute — hyresregleringens omvända verkan",
      "B": "Bostadsbristen i Stockholm — en växande utmaning",
      "C": "Fri hyressättning nu — så löser marknaden bostadsbristen",
      "D": "Hushållens skulder — en fara för svensk ekonomi"
